const PLACE = /\{(\d+)\}/g;
const HTTP_CODE = /^http-(\d{3})$/;

/** {@return true when the page has a text for this key} */
export function hasText(key) {
    return typeof key === 'string' && Object.hasOwn(TEXTS, key);
}

/**
 * @param {string} key
 * @param {...*} values put in as text
 * @returns {string} the text, or the key itself when there is none
 */
export function text(key, ...values) {
    if (!hasText(key)) {
        return String(key);
    }
    return TEXTS[key].replace(PLACE, (place, n) => (n < values.length ? String(values[n]) : place));
}

/**
 * @param {string} [code] the add-on's error code, a code of the page, or http-<status>
 * @param {string} [serverText] the server's text, shown when the page has none for the code
 * @returns {string}
 */
export function errorText(code, serverText) {
    if (hasText(`error.${code}`)) {
        return text(`error.${code}`);
    }
    const http = HTTP_CODE.exec(String(code));
    if (http) {
        return text('error.http', http[1]);
    }
    if (typeof serverText === 'string' && serverText.trim() !== '') {
        return serverText;
    }
    return text('error.unknown', code ?? 'unknown');
}
